package com.campus.student.api;
import java.time.Instant; import java.util.*; import com.campus.student.application.StudentManagementService; import com.campus.student.domain.*; import jakarta.validation.*; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.support.ServletUriComponentsBuilder;
@RestController @RequestMapping("/api/v1/admin/students") public class AdminStudentController { private final StudentManagementService service; public AdminStudentController(StudentManagementService s){service=s;} @PostMapping public ResponseEntity<Response> create(@Valid @RequestBody Request r){Student s=service.create(r.studentNumber(),r.fullName(),r.email(),r.organizationUnitId(),r.status());return ResponseEntity.created(ServletUriComponentsBuilder.fromCurrentRequest().path("/{studentId}").buildAndExpand(s.id()).toUri()).body(out(s));} @GetMapping public List<Response> list(){return service.list().stream().map(AdminStudentController::out).toList();} @GetMapping("/{studentId}") public Response get(@PathVariable UUID studentId){return out(service.get(studentId));} @PutMapping("/{studentId}") public Response update(@PathVariable UUID studentId,@Valid @RequestBody UpdateRequest r){return out(service.update(studentId,r.studentNumber(),r.fullName(),r.email(),r.organizationUnitId(),r.status(),r.expectedVersion()));} private static Response out(Student s){return new Response(s.id(),s.studentNumber(),s.fullName(),s.email(),s.organizationUnitId(),s.status().name(),s.rowVersion(),s.createdAt(),s.updatedAt());} public record Request(@NotBlank String studentNumber,@NotBlank String fullName,String email,@NotNull UUID organizationUnitId,StudentStatus status){} public record UpdateRequest(@NotBlank String studentNumber,@NotBlank String fullName,String email,@NotNull UUID organizationUnitId,@NotNull StudentStatus status,@NotNull @PositiveOrZero Long expectedVersion){} public record Response(UUID id,String studentNumber,String fullName,String email,UUID organizationUnitId,String status,long rowVersion,Instant createdAt,Instant updatedAt){} }
